#!/bin/bash
# ============================================================================
#  crear-lab5.sh — Instala el escenario Killercoda del Lab 5 (Clase 10, Módulo 4)
#  lab5-apparmor-k8s-condortech · backend kubernetes-kubeadm-1node
#  Compatible con macOS y Linux (base64 por stdin, shasum/sha256sum).
# ----------------------------------------------------------------------------
#  ANTES DE CORRERLO:
#   1. Ubícate en la carpeta raíz de tu repositorio de escenarios de Killercoda
#      (el que está enlazado a killercoda.com/cruzgio):   cd ~/ruta/a/tu/repo
#   2. No debe existir ya una carpeta lab5-apparmor-k8s-condortech (si existe, se renombra a .bak).
#   3. Luego ejecuta:   bash crear-lab5.sh
#  Al final te imprime el comando git completo para publicar.
# ============================================================================
set -e
if ! git rev-parse --is-inside-work-tree >/dev/null 2>&1; then
  echo "AVISO: esta carpeta no es un repositorio git. Sigo, pero recuerda que debe ser el repo de Killercoda."
fi
[ -d lab5-apparmor-k8s-condortech ] && mv lab5-apparmor-k8s-condortech lab5-apparmor-k8s-condortech.bak && echo "Carpeta previa renombrada a .bak"
TMP=$(mktemp /tmp/lab5.XXXXXX.tgz)
printf '%s' "" | base64 --decode > "$TMP"
if command -v sha256sum >/dev/null 2>&1; then GOT=$(sha256sum "$TMP" | cut -d' ' -f1); else GOT=$(shasum -a 256 "$TMP" | cut -d' ' -f1); fi
[ "$GOT" = "d32d79726019d3dcf510c97e6018b3ab2026c116add70b04f0e9e4a89f437503" ] || { echo "ERROR: la verificación de integridad falló"; exit 1; }
tar -xzf "$TMP" && rm -f "$TMP"
chmod +x lab5-apparmor-k8s-condortech/background.sh lab5-apparmor-k8s-condortech/assets/ct-* lab5-apparmor-k8s-condortech/assets/leer-config
echo
echo "✔ Escenario creado en ./lab5-apparmor-k8s-condortech ($(find lab5-apparmor-k8s-condortech -type f | wc -l | tr -d ' ') archivos)"
echo
echo "Para publicarlo, ejecuta este comando completo:"
echo
echo '  git add -A && git commit -m "Lab 5: AppArmor + Kubernetes (Cóndor Tech, clase 10)" && git push'
echo
echo "Luego abre: https://killercoda.com/cruzgio/scenario/lab5-apparmor-k8s-condortech"
echo "Primera prueba (tú, antes del lunes): ct-listo → ct-demo-intro → paso 1 a 6 con ct-check. Ver guía docente, sección «Validación previa»."
